INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Normalisierung immer alle Redundanzen entfernt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann kontrollierte Redundanzen lassen"}, {"text": "Ja", "correct": false, "because": "Zu absolut"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Datenbank normalisiere?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Normalisierungsformen gibt es?', 5, '[{"text": "1NF", "correct": true, "because": "Atomare Werte"}, {"text": "3NF", "correct": true, "because": "Transitive Abhängigkeiten"}, {"text": "Büroform", "correct": false, "because": "Kein Begriff"}, {"text": "Farbform", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Normalisierung reduziert Anomalien. b) Sie macht Datenbanken immer schneller.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Datenbank normalisiere?', 4, '[{"text": "Primärschlüssel", "correct": false, "because": "Sichert Einzigartigkeit"}, {"text": "Funktionale Abhängigkeiten", "correct": false, "because": "Bestimmen Struktur"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Normalisierung nur für große Datenbanken gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Datenbanken"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Normalisierung?', 3, '[{"text": "Reduzierung von Anomalien", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnellste Abfragen", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Normalisierung entscheidend?', 5, '[{"text": "1NF", "correct": true, "because": "Atomare Werte"}, {"text": "2NF", "correct": true, "because": "Partielle Abhängigkeiten"}, {"text": "Bürostruktur", "correct": false, "because": "Irrelevant"}, {"text": "Farbkodierung", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Normalisierung reduziert Redundanzen. b) Sie ist immer zeitaufwendig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": "false", "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Datenbank zu normalisieren?', 4, '[{"text": "Primärschlüssel", "correct": false, "because": "Sichert Einzigartigkeit"}, {"text": "Funktionale Abhängigkeiten", "correct": false, "because": "Bestimmen Struktur"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die 1NF die höchste Normalisierungsform?', 2, '[{"text": "Nein", "correct": true, "because": "Bis BCNF und höher"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Normalisierung?', 4, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Reduzierte Anomalien", "correct": true, "because": "Vermeidet Fehler"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Normalisierung nur für relationale Datenbanken gilt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Primär relational"}, {"text": "Nein", "correct": false, "because": "Hauptsächlich relational"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Datenbank effektiv zu normalisieren?', 3, '[{"text": "Funktionale Abhängigkeiten", "correct": true, "because": "Bestimmen Struktur"}, {"text": "Schnellste Methode", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die 2NF beseitigt partielle Abhängigkeiten. b) Normalisierung erhöht immer die Abfragegeschwindigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Normalisierung?', 5, '[{"text": "Datenredundanz", "correct": true, "because": "Wird reduziert"}, {"text": "Primärschlüssel", "correct": true, "because": "Sichert Einzigartigkeit"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Datenbank normalisiere?', 3, '[{"text": "Datenintegrität", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Normalisierungsstufen", "correct": false, "because": "Bestimmen Prozess"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Normalisierung immer für jede Datenbank notwendig?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Zu absolut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die 3NF alle transitiven Abhängigkeiten beseitigt?', 2, '[{"text": "Ja", "correct": true, "because": "Definition 3NF"}, {"text": "Nein", "correct": false, "because": "Kernprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für die Normalisierung?', 4, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
